mapper.select:

WHERE a.occurred_at >= #{from} AND a.occurred_at < #{to}


    AND a.scope_type='TENANT' AND a.actor_tenant_id=#{tenantId}


        AND a.store_id=#{storeId}
        AND a.action_code IN ('catalog.category.bind','catalog.category.unbind','catalog.category.change')

      AND a.action_code IN ('store.opening.draft','store.opening.revise','store.opening.open')



    AND a.scope_type='PLATFORM'

      AND =#{action}
      AND a.action_code NOT IN ('platform.audit.list','platform.audit.read')



AND a.actor_id=#{actorId}
AND a.resource_id=#{resourceId}

  AND (CASE WHEN p.id IS NOT NULL THEN 'SUCCEEDED' ELSE COALESCE(o.result_code,'UNKNOWN') END)=#{result}


  AND (a.occurred_at < #{cursorTime} OR (a.occurred_at=#{cursorTime} AND a.id < #{cursorId}))

ORDER BY a.occurred_at DESC,a.id DESC LIMIT #{limit}
